import itertools
cells=[]
for r in range(3,28):
    for c in range(3,28):
        v=g[r][c]
        if v in cyc: cells.append((r,c,idx(v)))
best=None
for a,b,k in itertools.product(range(5),repeat=3):
    err=sum(1 for r,c,i in cells if (a*r+b*c+k)%5!=i)
    if best is None or err<best[0]: best=(err,a,b,k)
print(best)

out=[row[:] for row in g]
for r in range(28):
    for c in range(28):
        if out[r][c]==0:
            if r<2 or c<2: out[r][c]=1
            elif r==2 or c==2: out[r][c]=4
            else: out[r][c]=cyc[(r+c)%5]
# sanity: check nonzero cells preserved, print rows around holes
for row in out: print(' '.join(map(str,row)))
